import java.util.*;

public class Main {
    int getDecimalValue(ListNode head) {
        StringBuilder bits = new StringBuilder();
        for (ListNode node = head; node != null; node = node.next) bits.append(node.val);   // collect every bit into a string, most-significant first
        return Integer.parseInt(bits.toString(), 2);                                          // parse the completed binary string directly
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode head = new ListNode(1, new ListNode(0, new ListNode(1)));
        System.out.println(solution.getDecimalValue(head));
    }
}

